-- Liga de Juntadas v11 — Temporadas manuales + historial congelado\n-- Ejecutar en Supabase > SQL Editor DESPUÉS de update_v9.sql / fix v9.7.\n\ncreate table if not exists public.seasons (\n  id uuid primary key default gen_random_uuid(),\n  name text not null,\n  emoji text not null default '🏆',\n  is_active boolean not null default false,\n  started_at timestamptz,\n  closed_at timestamptz,\n  created_by uuid not null references public.profiles(id),\n  final_standings jsonb,\n  awards jsonb,\n  created_at timestamptz not null default now()\n);\n\n-- Solo una temporada puede estar activa.\ncreate unique index if not exists seasons_only_one_active\n  on public.seasons ((is_active))\n  where is_active = true;\n\nalter table public.events add column if not exists season_id uuid references public.seasons(id) on delete restrict;\n\n-- Si ya había juntadas, las agrupamos en una temporada inicial para no perder historial.\ndo $$\ndeclare\n  legacy_id uuid;\nbegin\n  if exists (select 1 from public.events where season_id is null) then\n    select id into legacy_id from public.seasons order by created_at limit 1;\n    if legacy_id is null then\n      insert into public.seasons(name, emoji, is_active, started_at, created_by)\n      select 'Temporada inicial', '🏁', true, now(), id\n      from public.profiles\n      where role = 'admin'\n      order by id\n      limit 1\n      returning id into legacy_id;\n    end if;\n    update public.events set season_id = legacy_id where season_id is null;\n  end if;\nend $$;\n\n-- A partir de ahora toda juntada pertenece a una temporada.\nalter table public.events alter column season_id set not null;\n\nalter table public.seasons enable row level security;\n\ndrop policy if exists seasons_read on public.seasons;\ncreate policy seasons_read on public.seasons\nfor select to authenticated\nusing (true);\n\ndrop policy if exists seasons_admin_insert on public.seasons;\ncreate policy seasons_admin_insert on public.seasons\nfor insert to authenticated\nwith check (public.is_admin() and created_by = auth.uid());\n\ndrop policy if exists seasons_admin_update on public.seasons;\ncreate policy seasons_admin_update on public.seasons\nfor update to authenticated\nusing (public.is_admin())\nwith check (public.is_admin());\n\ndrop policy if exists seasons_admin_delete on public.seasons;\ncreate policy seasons_admin_delete on public.seasons\nfor delete to authenticated\nusing (public.is_admin());\n\nselect id, emoji, name, is_active, started_at, closed_at from public.seasons order by created_at;\n